@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{--ink:#e7e9dc;--muted:#878f84;--orange:#f07844;--lime:#bacd83;--bg:#101513;--line:rgba(227,232,215,.15);font-family:'DM Mono',monospace;color:var(--ink)}*{box-sizing:border-box}body{margin:0;background:#0d1210;overflow:hidden}#game-shell{position:relative;width:100vw;height:100dvh;min-height:500px;overflow:hidden;background:#182019}#game{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated}.scanlines{pointer-events:none;position:absolute;inset:0;z-index:2;background:repeating-linear-gradient(0deg,transparent 0px,rgba(0,0,0,.065) 1px,transparent 2px);opacity:.28}.screen{position:absolute;inset:0;z-index:3;background:linear-gradient(90deg,rgba(12,17,15,.97) 0%,rgba(12,17,15,.88) 41%,rgba(12,17,15,.24) 77%,rgba(12,17,15,.1)),linear-gradient(0deg,rgba(8,12,10,.75),transparent 25%,transparent 80%,rgba(8,12,10,.2);display:flex;flex-direction:column;padding:29px 5.2vw 23px}.menu-top,.menu-footer{display:flex;align-items:center;justify-content:space-between}.brand,.hud-brand{display:flex;align-items:center;gap:12px;font:800 15px 'Barlow Condensed',sans-serif;letter-spacing:1.9px}.brand small,.hud-brand small{display:block;color:#9da398;font:9px 'DM Mono',monospace;letter-spacing:1.2px;margin-top:3px}.brand-mark{width:35px;height:35px;border:1px solid rgba(240,120,68,.8);color:var(--orange);display:grid;place-items:center;font:900 23px 'Barlow Condensed';transform:skew(-7deg)}.status{font-size:9px;letter-spacing:1px;color:#a6aea1}.status i,.mission-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a6c574;box-shadow:0 0 9px #a6c574;margin-right:8px}.status b{color:var(--orange);margin:0 8px}.hero{width:min(510px,47vw);margin:auto 0 auto 6.2vw;padding-top:1.2vh}.eyebrow{font-size:10px;color:var(--orange);letter-spacing:2px;display:flex;align-items:center;gap:9px}.eyebrow-line{width:24px;height:1px;background:var(--orange)}h1{font:900 clamp(58px,7vw,92px)/.79 'Barlow Condensed',sans-serif;letter-spacing:-1px;margin:17px 0 17px;color:#e8e9de}h1 em{font-style:normal;color:var(--orange)}.hero-copy{font-size:11px;line-height:1.8;color:#a5aca1;margin:0 0 27px}.mode-label{font-size:9px;color:#d9ded0;letter-spacing:1.6px;margin-bottom:9px}.mode-label span{float:right;color:#7a8279}.mode-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.mode-card{position:relative;text-align:left;background:rgba(26,33,29,.82);border:1px solid rgba(223,230,212,.19);color:var(--ink);height:145px;padding:13px 15px;cursor:pointer;transition:.18s}.mode-card:hover{background:rgba(43,52,43,.9);transform:translateY(-2px)}.mode-card.selected{border-color:var(--orange);background:rgba(68,43,33,.52);box-shadow:inset 0 0 20px rgba(240,120,68,.055)}.mode-index{font-size:8px;letter-spacing:1px;color:#a6ada2}.mode-icon{position:absolute;right:13px;top:8px;font-size:26px;color:#8b9b66}.prop-icon{color:#d39c5f}.mode-card strong{display:block;font:800 25px/.82 'Barlow Condensed',sans-serif;letter-spacing:.5px;margin:12px 0 7px}.mode-desc{display:block;color:#a6ada1;font-size:8px;letter-spacing:-.3px}.mode-action{position:absolute;bottom:11px;left:15px;right:12px;border-top:1px solid var(--line);padding-top:8px;font-size:8px;letter-spacing:.7px;color:#d3d8cc}.mode-action b{float:right;color:var(--orange);font-size:13px;line-height:8px}.deploy{margin-top:11px;width:100%;height:40px;border:0;background:var(--orange);color:#171512;cursor:pointer;text-align:left;padding:0 15px;font:800 12px 'DM Mono',monospace;letter-spacing:2px}.deploy span{float:right;font-size:20px;line-height:17px}.deploy:hover{background:#ff9360}.menu-footer{font-size:8px;color:#8c958a;letter-spacing:.6px}.hidden{display:none!important}#hud{position:absolute;z-index:4;inset:0;pointer-events:none}.hud-top{position:absolute;top:22px;left:28px;right:28px;display:flex;align-items:center;justify-content:space-between}.hud-brand{font-size:12px}.hud-brand .brand-mark{width:29px;height:29px;font-size:19px}.hud-brand small{font-size:8px}.wave-box{position:absolute;left:50%;transform:translateX(-50%);text-align:center;font-size:10px;letter-spacing:1.4px}.wave-box b{display:block;color:var(--orange);font-size:8px;margin-top:5px}.hud-top>button{pointer-events:auto;background:rgba(14,18,16,.65);border:1px solid var(--line);color:white;width:34px;height:34px;cursor:pointer}.mission{position:absolute;top:82px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:10px;letter-spacing:1px;text-shadow:0 2px 6px black}.mission-sub{color:#aab1a4;font-size:8px;margin-left:12px}.hud-bottom{position:absolute;left:28px;right:28px;bottom:21px;display:flex;align-items:flex-end;justify-content:space-between;text-shadow:0 2px 7px #000}.health-panel{width:205px}.panel-label{font-size:9px;letter-spacing:1px;color:#d1d6c9}.panel-label span{float:right;color:#eef0e5}.health-track{height:5px;background:rgba(5,8,7,.8);margin:8px 0 5px;border:1px solid rgba(255,255,255,.2)}.health-track i{height:100%;width:100%;display:block;background:var(--lime);transition:width .25s}.health-caption{font-size:7px;letter-spacing:.6px;color:#a9b0a5}.health-caption b{color:var(--lime);float:right}.weapon-panel{text-align:center;width:230px}.weapon-meta{display:flex;justify-content:space-between;font-size:11px;letter-spacing:1px}.weapon-meta>span:last-child{font-size:17px}.weapon-meta i{font-style:normal;font-size:9px;color:#aaa}.weapon-art{font:22px monospace;color:#c5c7b9;letter-spacing:-5px;height:34px;filter:drop-shadow(0 1px 3px black)}.weapon-switch{display:flex;justify-content:center;gap:13px;font-size:7px;color:#b8beb0}.weapon-switch b{color:var(--orange)}.score-panel{text-align:right;width:150px}.score-panel strong{display:block;font:700 29px 'Barlow Condensed',sans-serif;margin-top:1px}.score-panel>span{font-size:8px;letter-spacing:1.2px;color:#aeb5a8}.wave-small{font-size:8px;color:var(--orange);margin-top:7px;letter-spacing:1px}.crosshair{position:absolute;left:50%;top:50%;width:20px;height:20px;transform:translate(-50%,-50%);opacity:.85}.crosshair i,.crosshair b{position:absolute;background:#e8edda;display:block;box-shadow:0 0 2px #121612}.crosshair i{width:1px;height:14px;left:9px;top:3px}.crosshair b{width:14px;height:1px;left:3px;top:9px}.toast{position:absolute;top:37%;left:50%;transform:translate(-50%,-50%);font-size:11px;letter-spacing:1.2px;color:var(--orange);text-shadow:0 2px 5px #000;opacity:0;transition:opacity .2s}.toast.show{opacity:1}.prop-hint{position:absolute;left:50%;top:62%;transform:translateX(-50%);background:rgba(12,16,14,.8);padding:10px 14px;font-size:9px;letter-spacing:1px;white-space:nowrap;border:1px solid var(--line)}.prop-hint b{color:var(--orange);margin-right:8px}.prop-hint span{color:#9ba296;margin-left:9px}.pause-panel{pointer-events:auto;position:absolute;inset:0;background:rgba(8,12,10,.88);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.pause-panel h2{font:800 50px/.9 'Barlow Condensed',sans-serif;margin:19px 0 10px}.pause-panel p{font-size:11px;color:#a6ada1;margin:0 0 24px}.pause-panel button{cursor:pointer;width:220px;padding:13px;margin:4px;background:var(--orange);border:0;font:700 10px 'DM Mono';letter-spacing:1.5px}.pause-panel button+button{background:transparent;color:#ddd;border:1px solid var(--line)}.mobile-controls{display:none}
@media(max-width:700px){#game-shell{min-height:100dvh}.screen{padding:18px 20px 17px;background:linear-gradient(90deg,rgba(12,17,15,.94),rgba(12,17,15,.63)),linear-gradient(0deg,rgba(8,12,10,.65),transparent)}.brand{font-size:12px}.status{font-size:7px}.hero{width:min(440px,100%);margin:auto 0;padding-top:20px}.eyebrow{font-size:9px}h1{font-size:64px;margin:14px 0}.hero-copy{font-size:10px;margin-bottom:20px}.mode-card{height:134px;padding:11px}.mode-card strong{font-size:23px}.mode-desc{font-size:7px}.mode-action{left:11px;font-size:7px}.menu-footer{font-size:7px;gap:5px}.menu-footer span:nth-child(2){display:none}.hud-top{top:12px;left:13px;right:13px}.mission{top:58px;font-size:8px}.mission-sub{display:none}.hud-bottom{left:13px;right:13px;bottom:12px}.health-panel{width:100px}.weapon-panel{width:150px}.weapon-switch{gap:5px;font-size:6px}.weapon-meta{font-size:9px}.weapon-meta>span:last-child{font-size:14px}.weapon-art{font-size:17px;height:26px}.score-panel{width:60px}.score-panel strong{font-size:23px}.score-panel .panel-label,.score-panel>span{font-size:7px}.wave-small{font-size:6px}.mobile-controls{display:block;position:absolute;inset:0;pointer-events:none}.mobile-controls button{pointer-events:auto;position:absolute;right:23px;bottom:128px;border:1px solid #eee8;background:#111b;color:white;border-radius:50%;width:59px;height:59px;font:700 9px 'DM Mono'}.mobile-controls button[data-touch="reload"]{right:90px;bottom:106px;width:40px;height:40px}.mobile-controls button[data-touch="switch"]{right:105px;bottom:160px;width:40px;height:40px;font-size:7px}.touch-stick{pointer-events:auto;position:absolute;left:23px;bottom:106px;width:100px;height:100px;border:1px solid rgba(255,255,255,.4);border-radius:50%;background:rgba(15,20,17,.35)}.touch-stick i{position:absolute;left:31px;top:31px;width:36px;height:36px;border-radius:50%;background:rgba(230,232,215,.35);border:1px solid rgba(255,255,255,.55)}.prop-hint{top:68%;font-size:7px}.prop-hint span{display:none}}
@media(max-height:700px) and (min-width:701px){.hero{transform:scale(.88);transform-origin:left center}.screen{padding-top:16px;padding-bottom:15px}.mode-card{height:129px}}

(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d',{alpha:false});
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const ui={menu:$('#menu'),hud:$('#hud'),deploy:$('#deploy'),wave:$('#wave-label'),waveState:$('#wave-state'),mission:$('#mission-text'),health:$('#health-value'),healthBar:$('#health-bar'),healthState:$('#health-state'),ammo:$('#ammo-value'),weapon:$('#weapon-name'),weaponArt:$('#weapon-art'),kills:$('#kill-value'),remaining:$('#wave-count'),toast:$('#toast'),hint:$('#prop-hint'),pause:$('#pause'),end:$('#end-panel')};
let W=480,H=270,fov=Math.PI/3,depth=[],last=0,mode='zombies',state='menu',selected='zombies',keys={},mouseDown=false,fireCooldown=0,toastTimer=0,player,entities=[],props=[],ragdolls=[],wave=0,kills=0,weapon=1,ammo=30,reserve=120,reloading=false,reloadTime=0,shotFlash=0,damageFlash=0,elapsed=0,propDisguise=0,propStay=0,won=false;
const mapText=['##################','#................#','#..##......##....#','#..#........#....#','#...........#....#','#..##............#','#......##........#','#................#','#......#.........#','#......#.........#','#......#.........#','#................#','#....##......##..#','#....#.......#...#','#...........##...#','#................#','#................#','##################'];
const map=mapText.map(r=>r.split('').map(c=>c==='#'?1:0));
function resize(){const a=innerWidth/innerHeight;H=240;W=Math.max(300,Math.round(H*a));canvas.width=W;canvas.height=H;depth=new Float32Array(W)}addEventListener('resize',resize);resize();
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),rnd=(a,b)=>a+Math.random()*(b-a);
function wallAt(x,y){return !map[Math.floor(y)]||map[Math.floor(y)][Math.floor(x)]!==0}
function clearShot(x1,y1,x2,y2){let d=Math.hypot(x2-x1,y2-y1),n=Math.ceil(d*8);for(let i=1;i<n;i++)if(wallAt(x1+(x2-x1)*i/n,y1+(y2-y1)*i/n))return false;return true}
function resetGame(which){mode=which;state='playing';ui.menu.classList.add('hidden');ui.hud.classList.remove('hidden');ui.pause.classList.add('hidden');ui.end.classList.add('hidden');player={x:9.55,y:9.55,angle:-Math.PI/2,health:100,speed:2.65};entities=[];props=[];ragdolls=[];wave=0;kills=0;weapon=1;ammo=30;reserve=120;reloading=false;elapsed=0;propDisguise=0;propStay=0;won=false;
  populateProps(); if(mode==='zombies'){nextWave();ui.mission.textContent='ELIMINATE ALL HOSTILES';ui.hint.classList.add('hidden')}else{wave=1;ui.wave.textContent='PROP HUNT';ui.waveState.textContent='HIDE OR FIGHT';ui.mission.textContent='SURVIVE THE HUNT — 90 SEC';ui.hint.classList.remove('hidden');for(let i=0;i<4;i++)spawnEnemy('hunter');showToast('HUNTERS ARE INBOUND');}
  updateHud(); try{canvas.requestPointerLock?.()}catch(_){}
}
function populateProps(){props=[];const spots=[[3.5,1.8,'crate'],[6.1,1.8,'barrel'],[12.7,1.9,'plant'],[15.4,4.7,'barrel'],[2.2,7.3,'plant'],[4.4,10.8,'crate'],[11.2,7.7,'barrel'],[14.6,10.4,'crate'],[2.5,14.4,'barrel'],[7.2,15.2,'plant'],[11.7,14.8,'crate'],[15.3,15.1,'plant'],[3.3,4.2,'barrel'],[9.2,2.4,'crate'],[13.8,7.5,'plant']];for(const [x,y,type] of spots)if(!wallAt(x,y))props.push({x,y,type,scale:type==='plant'?.78:.72});}
function spawnEnemy(type='zombie'){
 let x,y,tries=0;do{x=rnd(1.5,16.5);y=rnd(1.5,16.5);tries++}while((wallAt(x,y)||dist({x,y},player)<5||entities.some(e=>dist(e,{x,y})<1.2))&&tries<300);
 const hp=type==='hunter'?50:30+wave*8;entities.push({x,y,type,hp,maxHp:hp,alive:true,attack:0,speed:type==='hunter'?1.0:.52+Math.min(.5,wave*.035),phase:rnd(0,6),hit:0});
}
function nextWave(){wave++;for(let i=0;i<Math.min(3+wave*2,16);i++)spawnEnemy();ui.wave.textContent=`WAVE ${String(wave).padStart(2,'0')}`;ui.waveState.textContent='INCOMING';ui.mission.textContent=wave===1?'ELIMINATE ALL HOSTILES':`WAVE ${wave} — HOLD THE LINE`;showToast(`WAVE ${String(wave).padStart(2,'0')} — THEY'RE COMING`);}
function showToast(t){ui.toast.textContent=t;ui.toast.classList.add('show');toastTimer=2.2}
function updateHud(){ui.health.textContent=Math.max(0,Math.ceil(player.health));ui.healthBar.style.width=`${clamp(player.health,0,100)}%`;ui.healthBar.style.background=player.health<30?'#e56d4a':'#bacd83';ui.healthState.textContent=player.health>65?'STABLE':player.health>30?'WOUNDED':'CRITICAL';ui.healthState.style.color=player.health>65?'#bacd83':'#ef7953';ui.kills.textContent=String(kills).padStart(2,'0');ui.remaining.textContent=mode==='zombies'?`${entities.length} REMAINING`:`${Math.max(0,Math.ceil(90-elapsed))} SEC LEFT`;ui.weapon.textContent=weapon===1?'AK-47':'RPG-7';ui.ammo.innerHTML=weapon===1?`${ammo} <i>/ ${reserve}</i>`:`${ammo} <i>/ ${reserve}</i>`;ui.weaponArt.textContent=weapon===1?'╸━━━━━╾':'━◎━━━━╾';}
function fire(){if(state!=='playing'||reloading||fireCooldown>0)return;if(mode==='prop'&&propDisguise>0){showToast('FIRING BLOWS YOUR COVER');propStay=99;propDisguise=0;return}if(ammo<=0){showToast('PRESS R TO RELOAD');return}ammo--;fireCooldown=weapon===1?.105:.85;shotFlash=.09;propStay=99;if(weapon===1){fireAK()}else fireRPG();updateHud()}
function targetHit(e,damage){e.hp-=damage;e.hit=.12;if(e.hp<=0)killEnemy(e)}
function aimTarget(maxDist=13){let best=null,score=.15;for(const e of entities){if(!e.alive)continue;const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy);if(d>maxDist||!clearShot(player.x,player.y,e.x,e.y))continue;let da=Math.atan2(Math.sin(Math.atan2(dy,dx)-player.angle),Math.cos(Math.atan2(dy,dx)-player.angle));const s=Math.abs(da)+d*.002;if(Math.abs(da)<.18&&s<score){score=s;best=e}}return best}
function fireAK(){const e=aimTarget(16);if(e)targetHit(e,Math.random()<.22?48:26)}
function fireRPG(){const rocket={x:player.x+Math.cos(player.angle)*.48,y:player.y+Math.sin(player.angle)*.48,angle:player.angle,life:1.55};let ticks=0;const timer=setInterval(()=>{if(state!=='playing'||!rocket.life){clearInterval(timer);return}const speed=.26;rocket.x+=Math.cos(rocket.angle)*speed;rocket.y+=Math.sin(rocket.angle)*speed;rocket.life-=.035;ticks++;if(wallAt(rocket.x,rocket.y)||ticks>42){clearInterval(timer);explode(rocket.x,rocket.y);return}for(const e of entities)if(e.alive&&dist(e,rocket)<.42){clearInterval(timer);explode(rocket.x,rocket.y);return}},35);}
function explode(x,y){shotFlash=.2;for(const e of entities)if(e.alive&&dist(e,{x,y})<2.8&&clearShot(x,y,e.x,e.y))targetHit(e,Math.max(20,115-dist(e,{x,y})*27));if(dist(player,{x,y})<1.4)hurt(16);showToast('ROCKET IMPACT')}
function killEnemy(e){e.alive=false;kills++;ragdolls.push({x:e.x,y:e.y,type:e.type,age:0,spin:rnd(-7,7),kick:rnd(0,3),phase:e.phase});if(mode==='zombies'&&Math.random()<.28&&player.health<100){player.health=Math.min(100,player.health+8);showToast('FIELD KIT +8')}if(mode==='zombies'&&entities.filter(a=>a.alive).length===0){ui.waveState.textContent='SECTOR CLEAR';if(wave>=5){endGame(true)}else setTimeout(()=>{if(state==='playing'&&mode==='zombies')nextWave()},1800)}if(mode==='prop'&&entities.filter(a=>a.alive).length===0)endGame(true);updateHud()}
function hurt(n){player.health=Math.max(0,player.health-n);damageFlash=.38;updateHud();if(player.health<=0)endGame(false)}
function endGame(win){if(state!=='playing')return;state='ended';won=win;ui.end.classList.remove('hidden');$('#end-title').textContent=win?(mode==='prop'?'YOU BLENDED IN.':'SECTOR CLEARED.'):'YOU DIDN’T MAKE IT.';$('#end-copy').textContent=mode==='prop'?`${Math.max(0,Math.ceil(90-elapsed))} seconds hidden · ${kills} hunters dropped`:`${kills} hostiles eliminated · wave ${wave} reached`;document.exitPointerLock?.()}
function reload(){if(state!=='playing'||reloading||ammo===(weapon===1?30:1)||reserve<=0)return;reloading=true;reloadTime=weapon===1?1.45:1.9;showToast('RELOADING');}
function move(dt){let f=0,s=0;if(keys.KeyW||keys.ArrowUp)f++;if(keys.KeyS||keys.ArrowDown)f--;if(keys.KeyD) s++;if(keys.KeyA)s--;if(keys.ArrowRight&&!mouseLocked)speedTurn(dt,1);if(keys.ArrowLeft&&!mouseLocked)speedTurn(dt,-1);const mag=Math.hypot(f,s)||1,sp=player.speed*(keys.ShiftLeft||keys.ShiftRight?1.55:1);f=f/mag*sp*dt;s=s/mag*sp*dt;const ca=Math.cos(player.angle),sa=Math.sin(player.angle),dx=ca*f-sa*s,dy=sa*f+ca*s;collideMove(dx,dy,.2);if(mode==='prop'&&propDisguise>0){if(Math.hypot(dx,dy)>.002)propStay=0;else propStay+=dt;if(propStay>2)player.speed=0.85;else player.speed=2.65}else player.speed=2.65;}
let mouseLocked=false;document.addEventListener('pointerlockchange',()=>mouseLocked=document.pointerLockElement===canvas);function speedTurn(dt,d){player.angle+=d*2.15*dt}
function collideMove(dx,dy,r){if(!wallAt(player.x+dx+r*Math.sign(dx),player.y))player.x+=dx;if(!wallAt(player.x,player.y+dy+r*Math.sign(dy)))player.y+=dy}
function update(dt){if(state!=='playing')return;elapsed+=dt;fireCooldown=Math.max(0,fireCooldown-dt);shotFlash=Math.max(0,shotFlash-dt);damageFlash=Math.max(0,damageFlash-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}if(reloading){reloadTime-=dt;if(reloadTime<=0){const cap=weapon===1?30:1;const n=Math.min(cap-ammo,reserve);ammo+=n;reserve-=n;reloading=false;updateHud()}}
 move(dt);
 if(mouseDown||keys.Space)fire();
 for(const e of entities){if(!e.alive)continue;e.phase+=dt*5;e.hit=Math.max(0,e.hit-dt);const d=dist(e,player),dx=player.x-e.x,dy=player.y-e.y;if(d>.48){const speed=e.speed*(mode==='prop'&&propDisguise>0&&propStay>2?1.35:1);const vx=dx/d*speed*dt,vy=dy/d*speed*dt;if(!wallAt(e.x+vx+.16*Math.sign(vx),e.y))e.x+=vx;if(!wallAt(e.x,e.y+vy+.16*Math.sign(vy)))e.y+=vy}else{e.attack-=dt;if(e.attack<=0){hurt(e.type==='hunter'?9:8+wave);e.attack=e.type==='hunter'?1.0:1.25}}}
 for(const r of ragdolls)r.age+=dt;ragdolls=ragdolls.filter(r=>r.age<4.6);
 if(mode==='prop'){if(elapsed>=90){endGame(true)}if(elapsed>0&&Math.floor(elapsed)%16===0&&Math.floor(elapsed-dt)!==Math.floor(elapsed))showToast('HUNTERS CLOSING IN')}
 updateHud();}
