function showMenu(){state='menu';ui.end.classList.add('hidden');ui.pause.classList.add('hidden');ui.hud.classList.add('hidden');ui.menu.classList.remove('hidden');document.exitPointerLock?.()}
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){if(state==='playing')pauseGame();else if(state==='paused')resumeGame()}if(e.code==='Digit1'){weapon=1;updateHud()}if(e.code==='Digit2'){weapon=2;updateHud()}if(e.code==='KeyR')reload();if(e.code==='KeyQ')toggleDisguise();if(e.code==='Enter'&&state==='menu')resetGame(selected)});
